import subprocess, string
EXE="./executable"
def t(s):
    p = subprocess.run([EXE,"--symbols",".*"], input=(s+"\n").encode(), capture_output=True)
    return p.stdout.decode().strip()

# test all 2-char combos of symbols
chars = list("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")
found=[]
for a in chars:
    for b in chars:
        s=a+b
        r=t(s)
        if r!=s:
            found.append((s,r))
print(f"2-char mappings: {len(found)}")
for s,r in found:
    print(f"  {s!r} => {r!r}")

# 3-char combos that contain dash/arrow? brute force all 3-char with -<>!=~ etc limited
import itertools
subset = list("-<>!=~+*^|&/\\")
found3=[]
for tup in itertools.product(subset, repeat=3):
    s=''.join(tup)
    r=t(s)
    if r!=s:
        found3.append((s,r))
print(f"3-char mappings (subset): {len(found3)}")
for s,r in sorted(found3)[:100]:
    print(f"  {s!r} => {r!r}")
PY
python3 /tmp/brute_sym.py 2>&1 | head -n 200"}

