use clap::{Arg, ArgAction, Command};
use std::io::{self, Read, IsTerminal};
use std::process::ExitCode;

fn assets_dir() -> String {
    // try relative to exe
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let cand = dir.join("assets");
            if cand.is_dir() {
                return cand.to_string_lossy().to_string();
            }
            // also /workspace/assets
        }
    }
    "/workspace/assets".to_string()
}
fn print_help_long() {
    let p = format!("{}/help_long.txt", assets_dir());
    if let Ok(s) = std::fs::read_to_string(&p) {
        print!("{}", s);
    } else if let Ok(s) = std::fs::read_to_string("/workspace/assets/help_long.txt") {
        print!("{}", s);
    }
}
fn print_help_short() {
    let p = format!("{}/help_short.txt", assets_dir());
    if let Ok(s) = std::fs::read_to_string(&p) {
        print!("{}", s);
    } else if let Ok(s) = std::fs::read_to_string("/workspace/assets/help_short.txt") {
        print!("{}", s);
    }
}
fn print_version() {
    println!("srgn 0.14.1");
}
fn print_completions(shell: &str) {
    let p = format!("{}/comp_{}.txt", assets_dir(), shell);
    if let Ok(s) = std::fs::read_to_string(&p) {
        print!("{}", s);
    } else if let Ok(s) = std::fs::read_to_string(format!("/workspace/assets/comp_{}.txt", shell)) {
        print!("{}", s);
    }
}

fn build_cli() -> Command {
    Command::new("executable")
        .disable_help_flag(true)
