fn main() {
    // Manual pre-scan for help/version with order precedence
    let raw: Vec<String> = std::env::args().collect();
    // scan for -h/--help/-V/--version before -- separator
    let mut seen_dashdash = false;
    for i in 1..raw.len() {
        let a = &raw[i];
        if !seen_dashdash {
            if a == "--" { seen_dashdash = true; continue; }
            // handle combined shorts containing h/V? e.g., -hu, -V?
            // For simplicity, check exact and combined
            if a == "--help" { print_help_long(); std::process::exit(0); }
            if a == "--version" { print_version(); std::process::exit(0); }
            if a == "-h" { print_help_short(); std::process::exit(0); }
            if a == "-V" { print_version(); std::process::exit(0); }
            // combined shorts: if starts with - and not --, contains h or V
            if a.starts_with("-") && !a.starts_with("--") && a.len() > 2 {
                // e.g., -hu, -uh, -hv etc. Check if contains h or V
                // But need to be careful: -G with attached value like -G*.txt contains G, not h/V
                // For help, if contains h, treat as help? Original: -hu gives help, -uh gives help. So yes.
                if a.contains('h') {
                    // need to ensure it's not -G value? -G takes value, but -Gh? Unlikely. For now, if contains h and first char is -, treat as help if h is not part of value? Simplify: if a[1..].contains('h') then help
                    print_help_short(); std::process::exit(0);
                }
                if a.contains('V') {
                    print_version(); std::process::exit(0);
                }
            }
            // also handle --help=value? No, help takes no value, but --help=true would be error? Original: --help=true? Let's let clap handle (will error). So only exact --help.
        }
    }
    let cmd = build_cli();
    let m = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => e.exit(),
    };
    // handle help/version if present (for cases where they were not caught above? e.g., --help after --? No, after -- they are positionals, not flags. So above is sufficient. But also handle via clap matches for completeness)
    if m.get_flag("help") {
        // need to distinguish -h vs --help? We lost info. Check raw for which was used: if raw contains --help before -h? Use first occurrence.
        // Find first help occurrence in raw before --
        let mut seen = false;
        for i in 1..raw.len() {
            if raw[i]=="--" { break; }
            if raw[i]=="--help" { print_help_long(); std::process::exit(0); }
            if raw[i]=="-h" || (raw[i].starts_with("-") && !raw[i].starts_with("--") && raw[i].contains('h')) {
                print_help_short(); std::process::exit(0);
            }
        }
        print_help_long();
        std::process::exit(0);
    }
    if m.get_flag("version") {
        print_version();
        std::process::exit(0);
    }
    if let Some(shell) = m.get_one::<String>("completions") {
        print_completions(shell);
        std::process::exit(0);
    }
    // placeholder logic
    eprintln!("[placeholder] parsed ok scope={:?}", m.get_one::<String>("scope"));
    std::process::exit(0);
}
