use clap::{Arg, ArgAction, Command};
fn assets_dir() -> String {
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let cand = dir.join("assets");
            if cand.is_dir() { return cand.to_string_lossy().to_string(); }
        }
    }
    "/workspace/assets".to_string()
}
fn print_help_long() { let p = format!("{}/help_long.txt", assets_dir()); if let Ok(s) = std::fs::read_to_string(&p) { print!("{}", s); return; } if let Ok(s) = std::fs::read_to_string("/workspace/assets/help_long.txt") { print!("{}", s); } }
fn print_help_short() { let p = format!("{}/help_short.txt", assets_dir()); if let Ok(s) = std::fs::read_to_string(&p) { print!("{}", s); return; } if let Ok(s) = std::fs::read_to_string("/workspace/assets/help_short.txt") { print!("{}", s); } }
fn print_version() { println!("srgn 0.14.1"); }
