// helper to get raw order of flags for Usage generation
fn raw_contains(raw: &[String], long: &str, short: char) -> bool {
    for a in raw {
        if a == "--" { break; }
        if a == &format!("--{}", long) { return true; }
        if a.starts_with(&format!("--{}=", long)) { return true; }
        if a.starts_with("-") && !a.starts_with("--") {
            // combined shorts, but need to handle -G with value? For flags without value, each char counts
            // For simplicity, check if contains short char and long is bool flag
            if a[1..].contains(short) {
                // need to ensure it's not -G value? -G takes value, so -Gfoo contains G but not necessarily flag? For bool flags, ok.
                return true;
            }
        }
    }
    false
}

