    let has_upper = m.get_flag("upper");
    let has_lower = m.get_flag("lower");
    let has_titlecase = m.get_flag("titlecase");
    let has_normalize = m.get_flag("normalize");
    let has_german = m.get_flag("german");
    let has_symbols = m.get_flag("symbols");
