fn apply_symbols(s: &str, invert: bool) -> String {
    if !invert {
        // forward: longest-match left-to-right
        let mut out = String::new();
        let chars: Vec<char> = s.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            // check 3-char
            if i+2 < chars.len() {
                let tri: String = chars[i..i+3].iter().collect();
                let mapped = match tri.as_str() {
                    "---" => Some("—"),
                    "-->" => Some("⟶"),
                    "<--" => Some("⟵"),
                    "<->" => Some("↔"),
                    _ => None,
                };
                if let Some(m) = mapped {
                    out.push_str(m);
                    i+=3;
                    continue;
                }
            }
            if i+1 < chars.len() {
                let duo: String = chars[i..i+2].iter().collect();
                let mapped = match duo.as_str() {
                    "!=" => Some("≠"),
                    "--" => Some("–"),
                    "->" => Some("→"),
                    "<-" => Some("←"),
                    "<=" => Some("≤"),
                    "=>" => Some("⇒"),
                    ">=" => Some("≥"),
                    _ => None,
                };
                if let Some(m) = mapped {
                    out.push_str(m);
                    i+=2;
                    continue;
                }
            }
            out.push(chars[i]);
            i+=1;
        }
        out
    } else {
