fn is_all_lower(s: &str) -> bool {
    let mut has_cased = false;
    for ch in s.chars() {
        if ch.is_lowercase() { has_cased = true; }
        else if ch.is_uppercase() { return false; }
    }
    has_cased
}
fn is_all_upper(s: &str) -> bool {
    let mut has_cased = false;
    for ch in s.chars() {
        if ch.is_uppercase() { has_cased = true; }
        else if ch.is_lowercase() { return false; }
    }
    has_cased
}

fn titlecase_word(w: &str) -> String {
    if w.is_empty() { return w.to_string(); }
