        // find first cased char index
        let mut first_idx: Option<usize> = None;
        for (i,c) in chars.iter().enumerate() {
            if c.is_alphabetic() { first_idx = Some(i); break; }
        }
        if let Some(idx) = first_idx {
            let first = chars[idx];
            // special for ß at first: map to SS
            let first_up = if first == 'ß' { "SS".to_string() } else if first == 'ẞ' { "SS".to_string() } else { first.to_uppercase().collect::<String>() };
            // rest: lowercase each
            let mut rest = String::new();
            for c in chars.iter().skip(idx+1) {
