// ===== HELPERS =====
fn apply_symbols(s: &str, invert: bool) -> String {
    if !invert {
        let mut out = String::new();
        let chars: Vec<char> = s.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if i+2 < chars.len() {
                let tri: String = chars[i..i+3].iter().collect();
                let m = match tri.as_str() {
                    "---" => Some("—"), "-->" => Some("⟶"), "<--" => Some("⟵"), "<->" => Some("↔"), _ => None,
                };
                if let Some(mm) = m { out.push_str(mm); i+=3; continue; }
            }
            if i+1 < chars.len() {
                let duo: String = chars[i..i+2].iter().collect();
                let m = match duo.as_str() {
                    "!=" => Some("≠"), "--" => Some("–"), "->" => Some("→"), "<-" => Some("←"), "<=" => Some("≤"), "=>" => Some("⇒"), ">=" => Some("≥"), _ => None,
                };
                if let Some(mm) = m { out.push_str(mm); i+=2; continue; }
            }
            out.push(chars[i]); i+=1;
        }
        out
    } else {
        let mut out = String::new();
        for ch in s.chars() {
            match ch {
                '≠' => out.push_str("!="), '→' => out.push_str("->"), '⟶' => out.push_str("-->"), '⟵' => out.push_str("<--"), '↔' => out.push_str("<->"), '⇒' => out.push_str("=>"), '←' => out.push_str("<-"), '≤' => out.push_str("<="), '≥' => out.push_str(">="), '–' => out.push_str("--"), '—' => out.push_str("---"), _ => out.push(ch),
            }
        }
        out
    }
