fn titlecase_word(w: &str) -> String {
    if w.is_empty() { return w.to_string(); }
    if !(is_all_lower(w) || is_all_upper(w)) { return w.to_string(); }
    let chars: Vec<char> = w.chars().collect();
    let mut first_idx: Option<usize> = None;
    for (i,c) in chars.iter().enumerate() { if c.is_alphabetic() { first_idx = Some(i); break; } }
    if let Some(idx) = first_idx {
        let first = chars[idx];
        let first_up = if first == 'ß' || first == 'ẞ' { "SS".to_string() } else { first.to_uppercase().collect::<String>() };
        let mut rest = String::new();
        for c in chars.iter().skip(idx+1) { rest.push_str(&c.to_lowercase().collect::<String>()); }
        let mut prefix = String::new();
        for c in chars.iter().take(idx) { prefix.push(*c); }
        format!("{}{}{}", prefix, first_up, rest)
    } else { w.to_string() }
}
