fn validate_replacement(repl: &str) -> Result<(), String> {
    // Check \ escapes: allowed \n \r \t \\ \b \f \' \" \xHH \uHHHH
    let chars: Vec<char> = repl.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' {
            if i+1 >= chars.len() { return Err(repl.to_string()); }
            let nxt = chars[i+1];
            match nxt {
                'n'|'r'|'t'|'\\'|'b'|'f'|'\''|'"' => { i+=2; continue; }
                'x' => {
                    if i+3 < chars.len() && chars[i+2].is_ascii_hexdigit() && chars[i+3].is_ascii_hexdigit() { i+=4; continue; }
                    else { return Err(repl.to_string()); }
                }
                'u' => {
                    if i+5 < chars.len() && chars[i+2].is_ascii_hexdigit() && chars[i+3].is_ascii_hexdigit() && chars[i+4].is_ascii_hexdigit() && chars[i+5].is_ascii_hexdigit() { i+=6; continue; }
                    else { return Err(repl.to_string()); }
                }
                _ => return Err(repl.to_string()),
            }
        } else { i+=1; }
    }
    Ok(())
}
fn unescape_replacement(repl: &str) -> String {
    // Convert \ escapes to actual chars (after validation, so all valid)
