                't' => { out.push('\t'); i+=2; },
                '\\' => { out.push('\\'); i+=2; },
                'b' => { out.push('\x08'); i+=2; },
                'f' => { out.push('\x0C'); i+=2; },
                '\'' => { out.push('\''); i+=2; },
                '"' => { out.push('"'); i+=2; },
                'x' => {
