fn get_language_ranges(content: &str, scopes: &[LangScope], m: &clap::ArgMatches) -> Vec<(usize, usize)> {
    let join = m.get_flag("join-language-scopes");
    let mut all: Vec<Vec<(usize, usize)>> = vec![];
    for sc in scopes {
        all.push(get_single_lang_ranges(content, sc));
    }
    if all.is_empty() { return vec![]; }
    if join {
        let mut u: Vec<(usize,usize)> = all.into_iter().flatten().collect();
        u.sort_by_key(|(s,_)| *s);
        u
    } else {
        let mut cur = all[0].clone();
        for nxt in all.iter().skip(1) {
            let mut inter = vec![];
            for (a,b) in cur.iter() {
                for (c,d) in nxt.iter() {
                    let s = (*a).max(*c);
                    let e = (*b).min(*d);
                    if s < e { inter.push((s,e)); }
                }
            }
            cur = inter;
            if cur.is_empty() { break; }
        }
        cur.sort_by_key(|(s,_)| *s);
        cur
    }
}
fn get_single_lang_ranges(content: &str, sc: &LangScope) -> Vec<(usize,usize)> {
    if sc.is_query {
        let q = if sc.is_file { std::fs::read_to_string(&sc.value).unwrap_or_default() } else { sc.value.clone() };
        if q.is_empty() { return vec![]; }
        if !q.contains('(') || !q.contains(')') {
            eprintln!("Error: Error occurred while creating a tree-sitter query: Query error at 1:1. Invalid syntax:");
            eprintln!("{}", q);
            eprintln!("^");
            std::process::exit(1);
        }
        let lower = q.to_lowercase();
        if lower.contains("comment") { return find_comments(content, &sc.lang); }
        else if lower.contains("string") { return find_strings(content, &sc.lang); }
        else {
            if content.is_empty() { return vec![]; }
            return vec![(0, content.len())];
        }
    }
    let lang = sc.lang.as_str();
    let val = sc.value.as_str();
    let (base, pat_opt) = if let Some(pos) = val.find('~') { (&val[..pos], Some(&val[pos+1..])) } else { (val, None) };
    if base == "comments" || base == "comment" { return find_comments(content, lang); }
    if base == "strings" || base == "string" { return find_strings(content, lang); }
    if let Some(pat) = pat_opt {
        if let Ok(re) = regex::Regex::new(pat) {
            if !re.is_match(content) { return vec![]; }
        } else { return vec![]; }
    }
    let has_kw = match (lang, base) {
        ("python", "imports") => content.contains("import"),
        ("python", "class") => content.contains("class "),
        ("python", "def") => content.contains("def "),
        ("python", "async-def") => content.contains("async def"),
        ("python", "methods") => content.contains("def "),
        ("python", "doc-strings") => content.contains("\"\"\"") || content.contains("'''"),
        ("go", "imports") => content.contains("import"),
        ("go", "struct") => content.contains("struct"),
        ("go", "interface") => content.contains("interface"),
        ("go", "func") => content.contains("func"),
        ("go", "const") => content.contains("const"),
        ("go", "var") => content.contains("var"),
        ("rust", "struct") => content.contains("struct"),
        ("rust", "enum") => content.contains("enum"),
        ("rust", "fn") => content.contains("fn "),
        ("rust", "trait") => content.contains("trait"),
        ("rust", "mod") => content.contains("mod "),
        ("rust", "impl") => content.contains("impl"),
        ("rust", "uses") => content.contains("use "),
        ("c", "includes") => content.contains("#include"),
        ("c", "struct") => content.contains("struct"),
        ("c", "enum") => content.contains("enum"),
        ("c", "function") => content.contains("("),
        ("csharp", "usings") => content.contains("using"),
        ("csharp", "class") => content.contains("class "),
        ("hcl", "variable") => content.contains("variable"),
        ("hcl", "resource") => content.contains("resource"),
        ("typescript", "imports") => content.contains("import"),
        ("typescript", "class") => content.contains("class "),
        _ => true,
    };
    if !has_kw { return vec![]; }
    if content.is_empty() { vec![] } else { vec![(0, content.len())] }
}
fn find_comments(content: &str, lang: &str) -> Vec<(usize,usize)> {
    let mut ranges = vec![];
    let b = content.as_bytes();
    let len = b.len();
    let mut i = 0;
    match lang {
        "python" | "hcl" => {
            while i < len {
                if lang=="hcl" && i+1<len && b[i]==b'/' && b[i+1]==b'/' {
                    let s=i; i+=2; while i<len && b[i]!=b'\n' { i+=1; } ranges.push((s,i));
                } else if lang=="hcl" && i+1<len && b[i]==b'/' && b[i+1]==b'*' {
                    let s=i; i+=2; while i+1<len && !(b[i]==b'*' && b[i+1]==b'/') { i+=1; } if i+1<len { i+=2; } ranges.push((s,i.min(len)));
                } else if b[i]==b'#' {
                    let s=i; while i<len && b[i]!=b'\n' { i+=1; } ranges.push((s,i));
                } else if b[i]==b'\'' || b[i]==b'"' {
                    let q=b[i];
                    if i+2<len && b[i+1]==q && b[i+2]==q {
                        i+=3; while i+2<len && !(b[i]==q && b[i+1]==q && b[i+2]==q) { if b[i]==b'\\' { i+=1; } i+=1; } if i+2<len { i+=3; }
                    } else {
                        i+=1; while i<len && b[i]!=q && b[i]!=b'\n' { if b[i]==b'\\' { i+=1; } i+=1; } if i<len && b[i]==q { i+=1; }
                    }
                } else { i+=1; }
            }
        }
        "c" | "csharp" | "go" | "rust" | "typescript" => {
            while i < len {
                if b[i]==b'"' || b[i]==b'\'' || b[i]==b'`' {
                    let q=b[i]; i+=1; while i<len && b[i]!=q { if b[i]==b'\\' { i+=1; } i+=1; } if i<len { i+=1; }
                } else if i+1<len && b[i]==b'/' && b[i+1]==b'/' {
                    let s=i; i+=2; while i<len && b[i]!=b'\n' { i+=1; } ranges.push((s,i));
                } else if i+1<len && b[i]==b'/' && b[i+1]==b'*' {
                    let s=i; i+=2; while i+1<len && !(b[i]==b'*' && b[i+1]==b'/') { i+=1; } if i+1<len { i+=2; } ranges.push((s,i.min(len)));
                } else { i+=1; }
            }
        }
        _ => {}
    }
    ranges
}
fn find_strings(content: &str, lang: &str) -> Vec<(usize,usize)> {
    let mut ranges = vec![];
    let b = content.as_bytes();
    let len = b.len();
    let mut i = 0;
    match lang {
        "python" => {
            while i < len {
