                        let e=i; if i+2<len { i+=3; }
                        ranges.push((s,e));
                    } else {
                        i+=1; let s=i;
                        while i<len && b[i]!=q && b[i]!=b'\n' { if b[i]==b'\\' { i+=1; } i+=1; }
                        let e=i; if i<len && b[i]==q { i+=1; }
                        ranges.push((s,e));
                    }
                } else { i+=1; }
            }
        }
        "c" | "go" => {
            while i < len {
                if i+1<len && b[i]==b'/' && (b[i+1]==b'/' || b[i+1]==b'*') {
                    if b[i+1]==b'/' { i+=2; while i<len && b[i]!=b'\n' { i+=1; } }
                    else { i+=2; while i+1<len && !(b[i]==b'*' && b[i+1]==b'/') { i+=1; } if i+1<len { i+=2; } }
                } else if b[i]==b'"' {
                    let s=i; i+=1; while i<len && b[i]!=b'"' { if b[i]==b'\\' { i+=1; } i+=1; } if i<len { i+=1; } ranges.push((s,i.min(len)));
                } else { i+=1; }
            }
        }
        _ => {
            let with_quotes = match lang { "rust"|"typescript" => false, _ => true };
            while i < len {
                if i+1<len && b[i]==b'/' && (b[i+1]==b'/' || b[i+1]==b'*') {
                    if b[i+1]==b'/' { i+=2; while i<len && b[i]!=b'\n' { i+=1; } }
                    else { i+=2; while i+1<len && !(b[i]==b'*' && b[i+1]==b'/') { i+=1; } if i+1<len { i+=2; } }
                } else if b[i]==b'"' || b[i]==b'\'' || b[i]==b'`' {
                    let q=b[i]; let s=i; i+=1; let inner_s=i;
                    while i<len && b[i]!=q { if b[i]==b'\\' { i+=1; } i+=1; }
                    let inner_e=i; if i<len { i+=1; }
                    if with_quotes { ranges.push((s,i.min(len))); } else { ranges.push((inner_s,inner_e)); }
                } else { i+=1; }
            }
        }
    }
    ranges
}
