fn process_content(m: &clap::ArgMatches, lang_scopes: &[LangScope], scope_str: &str, repl_opt: Option<&str>, content: &str) -> (String, bool) {
    let has_actions = m.get_flag("upper") || m.get_flag("lower") || m.get_flag("titlecase") || m.get_flag("normalize") || m.get_flag("german") || m.get_flag("symbols") || m.get_flag("delete") || m.get_flag("squeeze") || repl_opt.is_some();
    let has_literal = m.get_flag("literal-string");
    let has_invert = m.get_flag("invert");
    let has_naive = m.get_flag("german-naive");
    let has_prefer = m.get_flag("german-prefer-original");
    let lang_ranges: Option<Vec<(usize,usize)>> = if lang_scopes.is_empty() { None } else { Some(get_language_ranges(content, lang_scopes, m)) };
    let pattern = if has_literal { regex::escape(scope_str) } else { scope_str.to_string() };
    let re = match regex::Regex::new(&pattern) {
        Ok(r) => r,
        Err(e) => { eprintln!("Error: Failed building regex"); eprintln!(""); eprintln!("Caused by:"); eprintln!("    Invalid regex: {}", e); std::process::exit(1); }
    };
    if let Some(repl) = repl_opt {
        if let Err(msg) = validate_replacement(repl) {
            eprintln!("Error: Failed building replacement string"); eprintln!(""); eprintln!("Caused by:"); eprintln!("    Contains invalid escape sequences: '{}'", msg); std::process::exit(1);
        }
    }
    if !has_actions {
        for mat in re.find_iter(content) {
            if mat.as_str().is_empty() { continue; }
            let s = mat.start(); let e = mat.end();
            let keep = if let Some(ref rs) = lang_ranges { rs.iter().any(|(a,b)| s>=*a && e<=*b) } else { true };
            if keep { return (content.to_string(), true); }
        }
        return (content.to_string(), false);
    }
    // collect matches
    struct MI { s: usize, e: usize, groups: Vec<Option<String>>, named: std::collections::HashMap<String,String>, whole: String }
    let mut all: Vec<MI> = vec![];
    for caps in re.captures_iter(content) {
        let mat = caps.get(0).unwrap();
        if mat.as_str().is_empty() { continue; }
        let s = mat.start(); let e = mat.end();
        let keep = if let Some(ref rs) = lang_ranges { rs.iter().any(|(a,b)| s>=*a && e<=*b) } else { true };
        if !keep { continue; }
        let mut groups: Vec<Option<String>> = vec![];
        for i in 0..caps.len() { groups.push(caps.get(i).map(|mm| mm.as_str().to_string())); }
        let mut nm = std::collections::HashMap::new();
        for n in re.capture_names().flatten() {
            if let Some(mm) = caps.name(n) { nm.insert(n.to_string(), mm.as_str().to_string()); }
        }
        all.push(MI{ s, e, groups, named: nm, whole: mat.as_str().to_string() });
    }
    if all.is_empty() { return (content.to_string(), false); }
    let has_delete = m.get_flag("delete");
    if has_delete {
        let mut out = String::new();
        let mut last = 0;
        for mi in all { out.push_str(&content[last..mi.s]); last = mi.e; }
        out.push_str(&content[last..]);
        return (out, true);
    }
    let has_squeeze = m.get_flag("squeeze");
    let mut runs: Vec<Vec<MI>> = vec![];
    if has_squeeze {
        let mut cur: Vec<MI> = vec![];
        for mi in all {
            if cur.is_empty() { cur.push(mi); }
            else {
                let prev_e = cur.last().unwrap().e;
                if mi.s == prev_e { cur.push(mi); } else { runs.push(cur); cur = vec![mi]; }
            }
        }
        if !cur.is_empty() { runs.push(cur); }
