fn expand_replacement(tmpl: &str, caps: &regex::Captures) -> Result<String, String> {
    let unescaped = unescape_replacement(tmpl);
    let chars: Vec<char> = unescaped.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '$' {
            if i+1 >= chars.len() { out.push('$'); i+=1; continue; }
            let nxt = chars[i+1];
            if nxt == '$' { out.push('$'); i+=2; continue; }
            else if nxt == '{' {
                if let Some(end) = chars[i+2..].iter().position(|&c| c=='}') {
                    let name: String = chars[i+2..i+2+end].iter().collect();
                    if name.chars().all(|c| c.is_ascii_digit()) {
                        if let Ok(idx) = name.parse::<usize>() {
                            if let Some(mm) = caps.get(idx) { out.push_str(mm.as_str()); } else { return Err(name.clone()); }
                        } else { return Err(name.clone()); }
                    } else {
                        if let Some(mm) = caps.name(&name) { out.push_str(mm.as_str()); } else { return Err(name.clone()); }
                    }
                    i += 2 + end + 1; continue;
                } else { out.push('$'); i+=1; continue; }
            } else if nxt.is_ascii_digit() {
                let mut j = i+1;
                while j < chars.len() && chars[j].is_ascii_digit() { j+=1; }
                let num: String = chars[i+1..j].iter().collect();
                if let Ok(idx) = num.parse::<usize>() {
                    if let Some(mm) = caps.get(idx) { out.push_str(mm.as_str()); } else { return Err(num.clone()); }
                } else { return Err(num.clone()); }
                i = j; continue;
            } else if nxt.is_ascii_alphabetic() || nxt == '_' {
                let mut j = i+1;
                while j < chars.len() && (chars[j].is_ascii_alphanumeric() || chars[j]=='_') { j+=1; }
                let name: String = chars[i+1..j].iter().collect();
                if let Some(mm) = caps.name(&name) { out.push_str(mm.as_str()); } else { return Err(name.clone()); }
                i = j; continue;
            } else { out.push('$'); i+=1; continue; }
        } else { out.push(chars[i]); i+=1; }
    }
    Ok(out)
}

