fn expand_replacement_line(tmpl: &str, caps: &regex::Captures) -> Result<String, String> {
    // Same as expand_replacement but using caps directly (need to handle unescape + $)
    // Reuse expand_replacement logic (which already does unescape + expand using caps)
    expand_replacement(tmpl, caps)
}

fn expand_replacement(tmpl: &str, caps: &regex::Captures) -> Result<String, String> {
    let unescaped = unescape_replacement(tmpl);
    let chars: Vec<char> = unescaped.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '$' {
            if i+1 >= chars.len() { out.push('$'); i+=1; continue; }
            let nxt = chars[i+1];
            if nxt == '$' { out.push('$'); i+=2; continue; }
            else if nxt == '{' {
                if let Some(end) = chars[i+2..].iter().position(|&c| c=='}') {
                    let name: String = chars[i+2..i+2+end].iter().collect();
                    if name.chars().all(|c| c.is_ascii_digit()) {
                        if let Ok(idx) = name.parse::<usize>() {
                            if let Some(mm) = caps.get(idx) { out.push_str(mm.as_str()); } else { return Err(name.clone()); }
                        } else { return Err(name.clone()); }
                    } else {
                        if let Some(mm) = caps.name(&name) { out.push_str(mm.as_str()); } else { return Err(name.clone()); }
                    }
                    i += 2 + end + 1; continue;
                } else { out.push('$'); i+=1; continue; }
            } else if nxt.is_ascii_digit() {
                let mut j = i+1;
                while j < chars.len() && chars[j].is_ascii_digit() { j+=1; }
                let num: String = chars[i+1..j].iter().collect();
                if let Ok(idx) = num.parse::<usize>() {
                    if let Some(mm) = caps.get(idx) { out.push_str(mm.as_str()); } else { return Err(num.clone()); }
                } else { return Err(num.clone()); }
                i = j; continue;
            } else if nxt.is_ascii_alphabetic() || nxt == '_' {
                let mut j = i+1;
                while j < chars.len() && (chars[j].is_ascii_alphanumeric() || chars[j]=='_') { j+=1; }
                let name: String = chars[i+1..j].iter().collect();
                if let Some(mm) = caps.name(&name) { out.push_str(mm.as_str()); } else { return Err(name.clone()); }
                i = j; continue;
            } else { out.push('$'); i+=1; continue; }
        } else { out.push(chars[i]); i+=1; }
    }
    Ok(out)
}

fn print_search_files(filename: &str, content: &str, m: &clap::ArgMatches, lang_scopes: &[LangScope], scope_str: &str) {
    // For search mode with files: print "filename:line:cols:line_content" for each matching line (with pipe detection? For files, output is always with filename prefix, regardless of stdout tty? Let's see: for auto-discovery with pipe (our tests with capture, stdout is pipe), output was "a.py:1:0-7:# hello" (with filename). For tty, what would it be? Probably "a.py:1:# hello" or similar? But since files are involved, output is always with filename, even with tty? Need to handle stdout detection for files as well? For stdin search with tty, output was "1:# hello" (without (stdin), with line only). For files search with tty, likely "a.py:1:# hello" (with filename, line, no cols). Good: handle similarly.
    // For now, implement pipe version (with cols) and tty version (without cols, with line only).
    let stdout_det = m.get_one::<String>("stdout-detection").unwrap().as_str();
    let is_tty = match stdout_det { "force-tty" => true, "force-pipe" => false, _ => std::io::stdout().is_terminal() };
    // Find matches per line similar to stdin search but with filename
    let has_literal = m.get_flag("literal-string");
    let pattern = if has_literal { regex::escape(scope_str) } else { scope_str.to_string() };
    let re = regex::Regex::new(&pattern).unwrap();
    let lang_ranges: Option<Vec<(usize,usize)>> = if lang_scopes.is_empty() { None } else { Some(get_language_ranges(content, lang_scopes, m)) };
    let lines: Vec<&str> = content.split('\n').collect();
    let mut line_starts: Vec<usize> = vec![0];
    for (idx,ch) in content.char_indices() { if ch=='\n' { line_starts.push(idx+1); } }
    for (idx, line) in lines.iter().enumerate() {
        if idx >= line_starts.len() { break; }
        // Skip last empty split if content ends with \n? split('\n') on "a\n" gives ["a",""] - last "" should be ignored (no line). Check: if line is "" and idx == lines.len()-1 and content.ends_with('\n'), skip.
        if line.is_empty() && idx==lines.len()-1 && content.ends_with('\n') { continue; }
        let ls = line_starts[idx];
        let mut cols: Vec<String> = vec![];
        for mat in re.find_iter(line) {
            if mat.as_str().is_empty() { continue; }
            let abs_s = ls + mat.start(); let abs_e = ls + mat.end();
            let keep = if let Some(ref rs) = lang_ranges { rs.iter().any(|(a,b)| abs_s>=*a && abs_e<=*b) } else { true };
            if keep { cols.push(format!("{}-{}", mat.start(), mat.end())); }
        }
        if cols.is_empty() { continue; }
        let cols_str = cols.join(";");
        if is_tty {
            println!("{}:{}:{}", filename, idx+1, line);
        } else {
            println!("{}:{}:{}:{}", filename, idx+1, cols_str, line);
        }
    }
}

